inputs = ['hxgfx', 'iyw', 'byw', 'ag', 'cevkuy']
outputs = ['hxgfx', 'hyegix', 'byegix', 'ag', 'jhgeykkuy']

# Step 1: Find changed pairs
changed_pairs = []
for i in range(len(inputs)):
    if inputs[i] != outputs[i]:
        changed_pairs.append((i, inputs[i], outputs[i]))

print("Changed pairs:")
for idx, inp, outp in changed_pairs:
    print(f"  {idx}: '{inp}' -> '{outp}'")

# Step 2: For each changed pair, find minimal edit
print("\nAnalyzing transformations:")
for idx, inp, outp in changed_pairs:
    print(f"  '{inp}' -> '{outp}':")
    # Simple character-by-character analysis
    if len(inp) < len(outp):
        # Insertion case
        print(f"    Insertion of characters")
        # Look for common substring
        min_len = min(len(inp), len(outp))
        for i in range(min_len):
            if inp[i] != outp[i]:
                print(f"    First difference at position {i}: '{inp[i]}' vs '{outp[i]}'")
                break
        else:
            # All matching up to min_len, so insertion at end
            print(f"    Insertion at end: '{outp[len(inp):]}'")
    else:
        print(f"    Same length - substitution or deletion")

